import { createServer } from '/home/sandbox/workspace/node_modules/vite/dist/node/index.js';
import { JSDOM } from '/tmp/pwcheck/node_modules/jsdom/lib/api.js';

const dom = new JSDOM('<!doctype html><html><body><div id="root"></div></body></html>', { url: 'http://localhost/' });
const g = globalThis;
g.window = dom.window; g.document = dom.window.document; g.navigator = dom.window.navigator;
g.HTMLElement = dom.window.HTMLElement; g.Node = dom.window.Node; g.Event = dom.window.Event;
g.getComputedStyle = dom.window.getComputedStyle; g.MutationObserver = dom.window.MutationObserver;
g.requestAnimationFrame = (cb) => setTimeout(cb, 0); g.cancelAnimationFrame = (id) => clearTimeout(id);
g.matchMedia = () => ({ matches: false, addListener() {}, removeListener() {}, addEventListener() {}, removeEventListener() {} });
g.ResizeObserver = class { observe() {} unobserve() {} disconnect() {} };
g.IS_REACT_ACT_ENVIRONMENT = true;
dom.window.matchMedia = g.matchMedia; dom.window.ResizeObserver = g.ResizeObserver;

const server = await createServer({
  root: '/home/sandbox/workspace', configFile: '/home/sandbox/workspace/vite.config.ts',
  appType: 'custom', logLevel: 'error', server: { middlewareMode: true, hmr: false },
  ssr: { noExternal: ['@gravity-ui/uikit'] },
});
const failures = [];
const check = (name, ok, extra = '') => { console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${extra ? ' — ' + extra : ''}`); if (!ok) failures.push(name); };

try {
  const React = await import('/home/sandbox/workspace/node_modules/react/index.js');
  const { createRoot } = await import('/home/sandbox/workspace/node_modules/react-dom/client.js');
  const { act } = React;
  const { App } = await server.ssrLoadModule('/src/App.tsx');

  const errors = [];
  const origErr = console.error;
  console.error = (...a) => { errors.push(a.map(String).join(' ').slice(0, 300)); };

  const container = document.getElementById('root');
  const root = createRoot(container);
  await act(async () => { root.render(React.createElement(App)); });

  const email = document.querySelector('#login-email');
  const password = document.querySelector('#login-password');
  const checkbox = document.querySelector('input.g-checkbox__control');
  const submit = document.querySelector('button[type=submit]');
  check('email input exists with type=email', email?.type === 'email');
  check('password input exists with type=password', password?.type === 'password');
  check('checkbox exists', !!checkbox);
  check('submit button labelled Войти', submit?.textContent.trim() === 'Войти');
  check('copy button hidden', !document.querySelector('[data-qa*=copy]') && !document.querySelector('button[aria-label*="опир"]'));

  const setNative = (el, value) => {
    const proto = Object.getPrototypeOf(el);
    Object.getOwnPropertyDescriptor(proto, 'value').set.call(el, value);
    el.dispatchEvent(new dom.window.Event('input', { bubbles: true }));
  };
  await act(async () => { setNative(email, 'user@example.com'); });
  await act(async () => { setNative(password, 'hunter2'); });
  check('email value updates (controlled)', email.value === 'user@example.com', email.value);
  check('password value updates (controlled)', password.value === 'hunter2');

  check('checkbox starts unchecked', checkbox.checked === false);
  await act(async () => { checkbox.click(); });
  check('checkbox toggles on click', checkbox.checked === true);
  await act(async () => { checkbox.click(); });
  check('checkbox toggles back', checkbox.checked === false);

  // Label click on the Russian caption should also toggle the checkbox
  const captionEl = [...document.querySelectorAll('label')].find((l) => l.textContent.includes('Запомнить меня'));
  await act(async () => { captionEl.click(); });
  check('caption click toggles checkbox', checkbox.checked === true);

  // Submit: handler must prevent default (no navigation) and form must be submitted
  let submitted = false;
  const form = document.querySelector('form.login-form');
  form.addEventListener('submit', (e) => { submitted = true; if (!e.defaultPrevented) e.target.dataset.notPrevented = '1'; }, { once: true });
  await act(async () => { submit.click(); });
  check('submit event fires on form', submitted);
  check('submit default prevented (no reload)', form.dataset.notPrevented !== '1');

  await act(async () => { root.unmount(); });
  console.error = origErr;
  const relevant = errors.filter((e) => !/not wrapped in act|ReactDOMTestUtils|act\(/.test(e));
  check('no console errors during render/interaction', relevant.length === 0, relevant.join(' | ').slice(0, 600));
} catch (e) {
  console.error = console.error; console.log('ERROR', e && e.stack);
  failures.push('exception');
} finally {
  await server.close();
}
console.log(failures.length ? `\n${failures.length} FAILED` : '\nALL PASSED');
process.exitCode = failures.length ? 1 : 0;
EOF
